import{_ as i,c as s,o as e,a5 as t}from"./chunks/framework.DorIfSpC.js";const g=JSON.parse('{"title":"Claude Code 開發規則","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://blog.aidream.com.tw/public/docs/claude"}],["meta",{"property":"og:url","content":"https://blog.aidream.com.tw/public/docs/claude"}],["meta",{"property":"og:title","content":"Claude Code 開發規則 | 星智未來"}],["meta",{"name":"twitter:title","content":"Claude Code 開發規則 | 星智未來"}]]},"headers":[],"relativePath":"public/docs/claude.md","filePath":"public/docs/claude.md","lastUpdated":1768045843000}'),n={name:"public/docs/claude.md"};function l(o,a,d,r,h,p){return e(),s("div",null,[...a[0]||(a[0]=[t(`<h1 id="claude-code-開發規則" tabindex="-1">Claude Code 開發規則 <a class="header-anchor" href="#claude-code-開發規則" aria-label="Permalink to &quot;Claude Code 開發規則&quot;">​</a></h1><h2 id="核心框架-piv" tabindex="-1">核心框架：PIV <a class="header-anchor" href="#核心框架-piv" aria-label="Permalink to &quot;核心框架：PIV&quot;">​</a></h2><p>每次任務必須遵循 <strong>Planning → Implementation → Validation</strong> 流程。</p><h3 id="planning-規劃" tabindex="-1">Planning（規劃） <a class="header-anchor" href="#planning-規劃" aria-label="Permalink to &quot;Planning（規劃）&quot;">​</a></h3><p>在開始寫任何程式碼之前：</p><ol><li><strong>確認需求</strong>：如果指令模糊，先詢問釐清，不要自行猜測</li><li><strong>明確範圍</strong>：確認輸入、輸出、邊界條件</li><li><strong>拆解任務</strong>：大任務拆成小步驟，逐步執行</li><li><strong>說明計畫</strong>：開始前簡述你打算怎麼做，讓使用者確認</li></ol><h3 id="implementation-實作" tabindex="-1">Implementation（實作） <a class="header-anchor" href="#implementation-實作" aria-label="Permalink to &quot;Implementation（實作）&quot;">​</a></h3><p>執行時遵守以下原則：</p><ol><li><strong>一次只做一件事</strong>：每次只實作一個功能或修改一個檔案</li><li><strong>保持簡單</strong>：用最直接的方式解決問題</li><li><strong>不做沒被要求的事</strong>：不預留擴展、不加額外功能</li><li><strong>遵循專案慣例</strong>：觀察現有程式碼風格並保持一致</li></ol><h3 id="validation-驗證" tabindex="-1">Validation（驗證） <a class="header-anchor" href="#validation-驗證" aria-label="Permalink to &quot;Validation（驗證）&quot;">​</a></h3><p>完成後必須驗證：</p><ol><li><strong>執行測試</strong>：如果有測試，執行並確認通過</li><li><strong>展示結果</strong>：顯示相關的 <code>git diff</code> 或執行結果</li><li><strong>總結變更</strong>：簡述這次改了什麼</li></ol><hr><h2 id="三大黃金法則" tabindex="-1">三大黃金法則 <a class="header-anchor" href="#三大黃金法則" aria-label="Permalink to &quot;三大黃金法則&quot;">​</a></h2><h3 id="_1-small-steps-小步迭代" tabindex="-1">1. Small Steps（小步迭代） <a class="header-anchor" href="#_1-small-steps-小步迭代" aria-label="Permalink to &quot;1. Small Steps（小步迭代）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>✅ 正確做法：</span></span>
<span class="line"><span>- 一個 prompt 完成一個小功能</span></span>
<span class="line"><span>- 完成後等待確認再繼續</span></span>
<span class="line"><span>- 每個步驟都可獨立驗證</span></span>
<span class="line"><span></span></span>
<span class="line"><span>❌ 避免：</span></span>
<span class="line"><span>- 一次改動多個不相關的檔案</span></span>
<span class="line"><span>- 未經確認就連續執行多個大改動</span></span>
<span class="line"><span>- 產生難以審查的大量變更</span></span></code></pre></div><h3 id="_2-tdd-test-first-測試先行" tabindex="-1">2. TDD / Test First（測試先行） <a class="header-anchor" href="#_2-tdd-test-first-測試先行" aria-label="Permalink to &quot;2. TDD / Test First（測試先行）&quot;">​</a></h3><p>當使用者要求新功能時：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>建議流程：</span></span>
<span class="line"><span>1. 先詢問：「要我先寫測試案例嗎？」</span></span>
<span class="line"><span>2. 若同意，先寫測試，確認測試案例正確</span></span>
<span class="line"><span>3. 再實作程式碼讓測試通過</span></span>
<span class="line"><span>4. 執行測試驗證結果</span></span></code></pre></div><p>若專案已有測試：</p><ul><li>修改程式碼後主動執行相關測試</li><li>新增功能時建議補上對應測試</li></ul><h3 id="_3-yagni-不做不需要的事" tabindex="-1">3. YAGNI（不做不需要的事） <a class="header-anchor" href="#_3-yagni-不做不需要的事" aria-label="Permalink to &quot;3. YAGNI（不做不需要的事）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>✅ 只做：</span></span>
<span class="line"><span>- 使用者明確要求的功能</span></span>
<span class="line"><span>- 當前需要的最簡實作</span></span>
<span class="line"><span></span></span>
<span class="line"><span>❌ 不要：</span></span>
<span class="line"><span>- 預留「未來可能用到」的介面</span></span>
<span class="line"><span>- 加入未被要求的錯誤處理或功能</span></span>
<span class="line"><span>- 過度抽象或設計模式</span></span>
<span class="line"><span>- 自作主張的「優化」或「改進」</span></span></code></pre></div><hr><h2 id="溝通規則" tabindex="-1">溝通規則 <a class="header-anchor" href="#溝通規則" aria-label="Permalink to &quot;溝通規則&quot;">​</a></h2><h3 id="開始任務前" tabindex="-1">開始任務前 <a class="header-anchor" href="#開始任務前" aria-label="Permalink to &quot;開始任務前&quot;">​</a></h3><ul><li>如果需求不清楚，先提問</li><li>說明你理解的任務範圍，請使用者確認</li><li>若任務較大，提出拆解建議</li></ul><h3 id="執行過程中" tabindex="-1">執行過程中 <a class="header-anchor" href="#執行過程中" aria-label="Permalink to &quot;執行過程中&quot;">​</a></h3><ul><li>遇到需要決策的地方，暫停詢問</li><li>發現潛在問題，提出但不擅自處理</li><li>保持進度透明，讓使用者知道你在做什麼</li></ul><h3 id="完成任務後" tabindex="-1">完成任務後 <a class="header-anchor" href="#完成任務後" aria-label="Permalink to &quot;完成任務後&quot;">​</a></h3><ul><li>簡潔總結完成了什麼</li><li>展示驗證結果（測試、執行輸出等）</li><li>不要冗長解釋，使用者會自己看程式碼</li></ul><hr><h2 id="程式碼風格" tabindex="-1">程式碼風格 <a class="header-anchor" href="#程式碼風格" aria-label="Permalink to &quot;程式碼風格&quot;">​</a></h2><h3 id="通用原則" tabindex="-1">通用原則 <a class="header-anchor" href="#通用原則" aria-label="Permalink to &quot;通用原則&quot;">​</a></h3><ul><li>變數和函數命名要有意義</li><li>保持函數簡短，單一職責</li><li>註解解釋「為什麼」，而非「做什麼」</li><li>遵循專案現有的命名和格式慣例</li></ul><h3 id="錯誤處理" tabindex="-1">錯誤處理 <a class="header-anchor" href="#錯誤處理" aria-label="Permalink to &quot;錯誤處理&quot;">​</a></h3><ul><li>只處理預期內的錯誤情況</li><li>不要過度防禦性編程</li><li>錯誤訊息要有幫助性</li></ul><hr><h2 id="git-操作" tabindex="-1">Git 操作 <a class="header-anchor" href="#git-操作" aria-label="Permalink to &quot;Git 操作&quot;">​</a></h2><h3 id="commit-規範" tabindex="-1">Commit 規範 <a class="header-anchor" href="#commit-規範" aria-label="Permalink to &quot;Commit 規範&quot;">​</a></h3><ul><li>使用有意義的 commit message</li><li>格式：<code>type: brief description</code></li><li>類型：<code>feat</code>, <code>fix</code>, <code>refactor</code>, <code>test</code>, <code>docs</code>, <code>chore</code></li></ul><h3 id="操作原則" tabindex="-1">操作原則 <a class="header-anchor" href="#操作原則" aria-label="Permalink to &quot;操作原則&quot;">​</a></h3><ul><li>改動前確認當前分支</li><li>大改動前建議先 commit 現有進度</li><li>不確定的操作先詢問</li></ul><hr><h2 id="禁止事項" tabindex="-1">禁止事項 <a class="header-anchor" href="#禁止事項" aria-label="Permalink to &quot;禁止事項&quot;">​</a></h2><ol><li><strong>不要</strong>在未告知的情況下刪除檔案或程式碼</li><li><strong>不要</strong>修改使用者沒提到的檔案</li><li><strong>不要</strong>安裝未經同意的套件</li><li><strong>不要</strong>執行可能有破壞性的指令（如 <code>rm -rf</code>）</li><li><strong>不要</strong>在程式碼中留下 <code>TODO</code> 或未完成的部分而不說明</li></ol><hr><h2 id="文章上架指令" tabindex="-1">文章上架指令 <a class="header-anchor" href="#文章上架指令" aria-label="Permalink to &quot;文章上架指令&quot;">​</a></h2><p>當使用者說「把 xxx.md 上架到 xx 類別」時，自動執行以下步驟：</p><h3 id="類別對應" tabindex="-1">類別對應 <a class="header-anchor" href="#類別對應" aria-label="Permalink to &quot;類別對應&quot;">​</a></h3><table tabindex="0"><thead><tr><th>類別</th><th>目錄</th><th>索引頁</th></tr></thead><tbody><tr><td>AI</td><td><code>docs/ai/</code></td><td><code>docs/ai/index.md</code></td></tr><tr><td>機器人 / robot</td><td><code>docs/robot/</code></td><td><code>docs/robot/index.md</code></td></tr><tr><td>專案 / project</td><td><code>docs/project/</code></td><td><code>docs/project/index.md</code></td></tr></tbody></table><h3 id="上架步驟-自動執行" tabindex="-1">上架步驟（自動執行） <a class="header-anchor" href="#上架步驟-自動執行" aria-label="Permalink to &quot;上架步驟（自動執行）&quot;">​</a></h3><ol><li><strong>讀取文章</strong>：讀取指定的 <code>.md</code> 文件，提取標題（第一個 <code># </code> 開頭的行）</li><li><strong>確認文章位置</strong>：確保文章已在正確的分類目錄下（如 <code>docs/ai/xxx.md</code>）</li><li><strong>更新分類索引頁</strong>：在 <code>docs/{分類}/index.md</code> 的 <code>## Recent Posts</code> 下方第一行加入連結</li><li><strong>更新側邊欄</strong>：在 <code>docs/.vitepress/config.ts</code> 對應分類的 sidebar items 中，Index 之後加入文章</li><li><strong>更新首頁</strong>：在 <code>docs/index.md</code> 的 <code>## 📝 最新文章</code> 區塊最上方加入文章（需提供日期和摘要）</li><li><strong>本地預覽驗證</strong>：執行 <code>npm run build</code> 確認無錯誤</li></ol><h3 id="上架格式範例" tabindex="-1">上架格式範例 <a class="header-anchor" href="#上架格式範例" aria-label="Permalink to &quot;上架格式範例&quot;">​</a></h3><p><strong>分類索引頁格式</strong>：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">文章標題</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">](</span><span style="--shiki-light:#24292E;--shiki-light-text-decoration:underline;--shiki-dark:#E1E4E8;--shiki-dark-text-decoration:underline;">./文章檔名</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p><strong>側邊欄格式</strong>：</p><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">text</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;文章標題&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">link</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;/分類/文章檔名&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p><strong>首頁格式</strong>：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">### [</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">文章標題</span><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">](</span><span style="--shiki-light:#005CC5;--shiki-light-text-decoration:underline;--shiki-dark:#79B8FF;--shiki-dark-text-decoration:underline;">/分類/文章檔名</span><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;">**分類標籤**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> · YYYY-MM-DD</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">文章摘要（1-2 句話）</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">---</span></span></code></pre></div><h3 id="注意事項" tabindex="-1">注意事項 <a class="header-anchor" href="#注意事項" aria-label="Permalink to &quot;注意事項&quot;">​</a></h3><ul><li>首頁最新文章區塊只保留最新 5 篇，超過的移除</li><li>日期格式統一使用 <code>YYYY-MM-DD</code></li><li>分類標籤使用：<code>AI</code>、<code>機器人</code>、<code>專案</code></li><li>若使用者未提供日期和摘要，需詢問</li></ul><hr><h2 id="口訣" tabindex="-1">口訣 <a class="header-anchor" href="#口訣" aria-label="Permalink to &quot;口訣&quot;">​</a></h2><blockquote><p><strong>PIV 打底，小步走，測試領，不貪多。</strong></p></blockquote><ul><li><strong>P</strong>lanning：想清楚再動手</li><li><strong>I</strong>mplementation：一次一小步</li><li><strong>V</strong>alidation：驗證後才算完成</li><li><strong>Small Steps</strong>：小步迭代好追蹤</li><li><strong>TDD</strong>：測試先行有保障</li><li><strong>YAGNI</strong>：不做多餘的事</li></ul>`,66)])])}const k=i(n,[["render",l]]);export{g as __pageData,k as default};
